<?php require_once 'config.php'; $pdo=db(); $id=(int)($_GET['id']??0);$st=$pdo->prepare("SELECT * FROM bolsa WHERE id=? AND status='published'");$st->execute([$id]);$s=$st->fetch();if(!$s){http_response_code(404);$page_title='Bolsa não encontrada';require 'includes/header.php';echo '<div class="empty">Esta oportunidade não existe ou já não está publicada. <a class="text-link" href="bolsas.php">Voltar às bolsas</a></div>';require 'includes/footer.php';exit;}$page_title=$s['title'].' | Kuntima';require 'includes/header.php'; ?>
<div class="page-heading"><a class="text-link" href="bolsas.php">← Todas as bolsas</a><p style="margin-top:20px"><span class="tag"><?=e($s['funding_type'])?></span></p><h1><?=e($s['title'])?></h1><p><?=e($s['organization'])?> · <?=e($s['country'])?></p></div><div class="grid" style="grid-template-columns:minmax(0,2fr) minmax(250px,1fr)"><article class="card"><h3>Sobre esta oportunidade</h3><p><?=nl2br(e($s['description']))?></p><h3>Requisitos</h3><p><?=nl2br(e($s['requirements']?:'Consulte a instituição responsável para confirmar os requisitos.'))?></p><?php if($s['application_url']): ?><p><a class="text-link" target="_blank" rel="noopener" href="<?=e($s['application_url'])?>">Página oficial da candidatura ↗</a></p><?php endif; ?></article><aside class="card"><h3>Resumo</h3><p><strong>Nível</strong><br><?=e($s['study_level'])?></p><p><strong>Área</strong><br><?=e($s['field'])?></p><p><strong>Financiamento</strong><br><?=e($s['funding_type'])?></p><p><strong>Prazo</strong><br><?= $s['deadline']?e(date('d/m/Y',strtotime($s['deadline']))):'A confirmar' ?></p><?php if(logged_in() && ($_SESSION['user']['role']??'')==='student'): ?><form method="post" action="candidatar.php"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="scholarship_id" value="<?=$s['id']?>"><div class="field"><label for="motivation">Mensagem de motivação (opcional)</label><textarea name="motivation" id="motivation" placeholder="Conta brevemente porque tens interesse nesta bolsa."></textarea></div><button class="btn-primary" type="submit">Submeter candidatura</button></form><?php elseif(!logged_in()): ?><a class="btn-primary" style="width:100%" href="login.php">Entrar para candidatar-me</a><?php else: ?><p class="muted">A candidatura está disponível para contas de estudante.</p><?php endif; ?></aside></div><?php require 'includes/footer.php'; ?>
